beforeExample:
import java.io.File;
import java.io.IOException;

public class TempFileCreator {
    public void createAndUseTempFile(String name) throws IOException {
        File tempFile = File.createTempFile(name, ".tmp");
        System.out.println("Created temp file: " + tempFile.getAbsolutePath());
        // The file might persist if not explicitly deleted or marked for deletion.
    }
}

afterExample:
import java.io.File;
import java.io.IOException;

public class TempFileCreator {
    public void createAndUseTempFile(String name) throws IOException {
        File tempFile = File.createTempFile(name, ".tmp");
        tempFile.deleteOnExit();
        System.out.println("Created temp file: " + tempFile.getAbsolutePath());
        // The file is now marked for deletion on JVM exit.
    }
}

